-- Extension of native CRM/projects/subscriptions. No new accounts, processors or storage.
CREATE TABLE website_subscription_plans(id TEXT PRIMARY KEY CHECK(id IN('start','business','premium')),catalog_id TEXT NOT NULL UNIQUE REFERENCES commercial_catalog_codes(id) ON DELETE RESTRICT,current_revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE website_subscription_plan_versions(plan_id TEXT NOT NULL REFERENCES website_subscription_plans(id) ON DELETE RESTRICT,revision INTEGER NOT NULL CHECK(revision>0),config_json TEXT NOT NULL CHECK(json_valid(config_json)),created_by TEXT REFERENCES users(id),created_at INTEGER NOT NULL,PRIMARY KEY(plan_id,revision));
CREATE TRIGGER website_plan_version_immutable BEFORE UPDATE ON website_subscription_plan_versions BEGIN SELECT RAISE(ABORT,'immutable_plan_version'); END;
CREATE TRIGGER website_plan_version_preserved BEFORE DELETE ON website_subscription_plan_versions BEGIN SELECT RAISE(ABORT,'immutable_plan_version'); END;
CREATE TABLE website_subscription_requests(id TEXT PRIMARY KEY,lead_id TEXT NOT NULL UNIQUE REFERENCES leads(id) ON DELETE RESTRICT,plan_id TEXT NOT NULL REFERENCES website_subscription_plans(id),request_key TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,project_id TEXT UNIQUE REFERENCES projects(id) ON DELETE RESTRICT,created_at INTEGER NOT NULL);
CREATE TABLE website_subscription_projects(project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE RESTRICT,plan_id TEXT NOT NULL,plan_revision INTEGER NOT NULL,subscription_id TEXT NOT NULL UNIQUE REFERENCES subscriptions(id) ON DELETE RESTRICT,plan_snapshot_json TEXT NOT NULL CHECK(json_valid(plan_snapshot_json)),request_id TEXT UNIQUE REFERENCES website_subscription_requests(id) ON DELETE RESTRICT,current_order_id TEXT UNIQUE REFERENCES commerce_orders(id) ON DELETE RESTRICT,provider_subscription_id TEXT UNIQUE,billing_anchor_day INTEGER CHECK(billing_anchor_day BETWEEN 1 AND 31),revision INTEGER NOT NULL DEFAULT 1,content_revision INTEGER NOT NULL DEFAULT 1,allocation_key TEXT NOT NULL UNIQUE,allocation_hash TEXT NOT NULL,checkout_claim TEXT NOT NULL DEFAULT 'pending',revision_claim INTEGER NOT NULL DEFAULT 1,approved_revision INTEGER,approval_claim INTEGER NOT NULL DEFAULT 0,approved_by TEXT REFERENCES users(id),approved_at INTEGER,transition_requested_at INTEGER,created_at INTEGER NOT NULL,FOREIGN KEY(plan_id,plan_revision) REFERENCES website_subscription_plan_versions(plan_id,revision));
CREATE TABLE website_subscription_acceptances(order_id TEXT PRIMARY KEY REFERENCES commerce_orders(id) ON DELETE RESTRICT,project_id TEXT NOT NULL REFERENCES website_subscription_projects(project_id) ON DELETE RESTRICT,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,plan_id TEXT NOT NULL,plan_revision INTEGER NOT NULL,terms_hash TEXT NOT NULL,terms_snapshot_json TEXT NOT NULL CHECK(json_valid(terms_snapshot_json)),accepted_at INTEGER NOT NULL,FOREIGN KEY(plan_id,plan_revision) REFERENCES website_subscription_plan_versions(plan_id,revision));
CREATE TABLE website_subscription_periods(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES website_subscription_projects(project_id) ON DELETE RESTRICT,provider TEXT NOT NULL CHECK(provider IN('stripe','revolut')),provider_invoice_id TEXT NOT NULL,starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,change_limit INTEGER NOT NULL CHECK(change_limit>=0),created_at INTEGER NOT NULL,UNIQUE(provider,provider_invoice_id),UNIQUE(project_id,starts_at),CHECK(ends_at>starts_at));
CREATE INDEX website_subscription_current_period ON website_subscription_periods(project_id,starts_at,ends_at);
CREATE TABLE website_subscription_changes(proposal_id TEXT PRIMARY KEY REFERENCES project_proposals(id) ON DELETE RESTRICT,project_id TEXT NOT NULL REFERENCES website_subscription_projects(project_id),kind TEXT NOT NULL CHECK(kind IN('content','bug','security')),units INTEGER NOT NULL DEFAULT 1 CHECK(units BETWEEN 1 AND 20),reviewed_by TEXT REFERENCES users(id),submission_hash TEXT,period_id TEXT REFERENCES website_subscription_periods(id),created_at INTEGER NOT NULL);
CREATE TABLE website_subscription_consumption(proposal_id TEXT PRIMARY KEY REFERENCES website_subscription_changes(proposal_id) ON DELETE RESTRICT,period_id TEXT NOT NULL REFERENCES website_subscription_periods(id) ON DELETE RESTRICT,units INTEGER NOT NULL CHECK(units>0),created_at INTEGER NOT NULL);
-- Native proposal updates from any module must obey the same reviewed quota.
CREATE TRIGGER website_change_review BEFORE UPDATE OF status ON project_proposals WHEN NEW.status='done' AND EXISTS(SELECT 1 FROM website_subscription_changes WHERE proposal_id=NEW.id AND reviewed_by IS NULL) BEGIN SELECT RAISE(ABORT,'website_change_review_required'); END;
CREATE TRIGGER website_change_quota BEFORE UPDATE OF status ON project_proposals WHEN NEW.status='done' AND EXISTS(SELECT 1 FROM website_subscription_changes ch WHERE ch.proposal_id=NEW.id AND ch.kind='content') AND NOT EXISTS(SELECT 1 FROM website_subscription_consumption WHERE proposal_id=NEW.id)
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM website_subscription_changes ch JOIN website_subscription_periods per ON per.id=ch.period_id JOIN website_subscription_projects wp ON wp.project_id=ch.project_id JOIN subscriptions sub ON sub.id=wp.subscription_id WHERE ch.proposal_id=NEW.id AND per.project_id=ch.project_id AND sub.status='active' AND per.starts_at<=unixepoch()*1000 AND per.ends_at>unixepoch()*1000 AND coalesce((SELECT sum(units) FROM website_subscription_consumption WHERE period_id=per.id),0)+ch.units<=per.change_limit) THEN RAISE(ABORT,'website_change_quota_exceeded') END;
END;
CREATE TRIGGER website_change_consumed AFTER UPDATE OF status ON project_proposals WHEN NEW.status='done' AND EXISTS(SELECT 1 FROM website_subscription_changes WHERE proposal_id=NEW.id AND kind='content') BEGIN INSERT OR IGNORE INTO website_subscription_consumption(proposal_id,period_id,units,created_at) SELECT proposal_id,period_id,units,unixepoch()*1000 FROM website_subscription_changes WHERE proposal_id=NEW.id; END;
CREATE TRIGGER website_consumption_immutable BEFORE UPDATE ON website_subscription_consumption BEGIN SELECT RAISE(ABORT,'immutable_consumption'); END;
CREATE TRIGGER website_consumption_preserved BEFORE DELETE ON website_subscription_consumption BEGIN SELECT RAISE(ABORT,'immutable_consumption'); END;
