INSERT INTO website_subscription_plan_versions(plan_id,revision,config_json,created_at) VALUES('business',1,'{}',unixepoch()*1000);
INSERT INTO commercial_catalog_codes(id,entity_type,entity_key,display_name,sku,accounting_code,category,base_price_minor,currency,vat_basis_points,payment_route,payment_status,active,notes,created_at,updated_at,unit_label,price_model,billing_cycle,tax_status,preferred_payment_provider,invoice_provider) VALUES('website-sub-premium','service','website-sub-premium','Website prin abonament — Site Premium','AVY-WEB-SUB-PREMIUM','AVY-WEB-SUB-PREMIUM','website-subscription',NULL,'RON',0,'unconfigured','needs_configuration',1,'Dezvoltare inclusă 0 lei; tarif lunar și fiscalitate de confirmat.',unixepoch()*1000,unixepoch()*1000,'lună','fixed','monthly','unverified',NULL,'manual');
INSERT INTO website_subscription_plans(id,catalog_id) VALUES('premium','website-sub-premium');
INSERT INTO website_subscription_plan_versions(plan_id,revision,config_json,created_at) VALUES('premium',1,'{}',unixepoch()*1000);

CREATE TRIGGER website_period_no_overlap BEFORE INSERT ON website_subscription_periods WHEN EXISTS(SELECT 1 FROM website_subscription_periods p WHERE p.project_id=NEW.project_id AND NEW.starts_at<p.ends_at AND NEW.ends_at>p.starts_at AND p.provider_invoice_id<>NEW.provider_invoice_id) BEGIN SELECT RAISE(ABORT,'website_period_overlap'); END;
CREATE TRIGGER website_period_immutable BEFORE UPDATE ON website_subscription_periods BEGIN SELECT RAISE(ABORT,'immutable_paid_period'); END;
CREATE TRIGGER website_period_preserved BEFORE DELETE ON website_subscription_periods BEGIN SELECT RAISE(ABORT,'immutable_paid_period'); END;

CREATE INDEX website_consumption_period ON website_subscription_consumption(period_id);
CREATE INDEX website_changes_project ON website_subscription_changes(project_id,created_at DESC);
CREATE INDEX website_projects_created ON website_subscription_projects(created_at DESC,project_id);
CREATE INDEX website_requests_created ON website_subscription_requests(created_at DESC);
CREATE TRIGGER website_request_notice AFTER INSERT ON website_subscription_requests
BEGIN
 INSERT OR IGNORE INTO operation_notifications(id,user_id,deduplication_key,title,body,destination,created_at,category,priority)
 SELECT lower(hex(randomblob(16))),u.id,'website-request:'||NEW.id||':'||u.id,'Solicitare · Website prin abonament','Un brief nou așteaptă evaluare și alocare.','/profil?tab=website-subscriptions',NEW.created_at,'activity','important'
 FROM users u JOIN platform_principals principal ON principal.email=u.email COLLATE NOCASE AND principal.status='active' WHERE u.disabled_at IS NULL AND u.email_verified=1 AND EXISTS(SELECT 1 FROM user_roles r WHERE r.user_id=u.id AND r.role='admin');
END;

-- Requests made from the existing project portal enter the same triage/quota.
CREATE TRIGGER website_native_proposal AFTER INSERT ON project_proposals WHEN EXISTS(SELECT 1 FROM website_subscription_projects WHERE project_id=NEW.project_id)
BEGIN INSERT OR IGNORE INTO website_subscription_changes(proposal_id,project_id,kind,period_id,created_at) VALUES(NEW.id,NEW.project_id,'content',(SELECT id FROM website_subscription_periods WHERE project_id=NEW.project_id AND starts_at<=unixepoch()*1000 AND ends_at>unixepoch()*1000 ORDER BY starts_at DESC LIMIT 1),NEW.created_at); END;

CREATE TRIGGER website_acceptance_immutable BEFORE UPDATE ON website_subscription_acceptances BEGIN SELECT RAISE(ABORT,'immutable_terms_acceptance'); END;
CREATE TRIGGER website_acceptance_preserved BEFORE DELETE ON website_subscription_acceptances BEGIN SELECT RAISE(ABORT,'immutable_terms_acceptance'); END;
CREATE TRIGGER website_client_approval BEFORE UPDATE OF status,banner_status ON projects WHEN EXISTS(SELECT 1 FROM website_subscription_projects w WHERE w.project_id=NEW.id AND (NEW.status IN('live','maintenance') OR NEW.banner_status='online') AND coalesce(w.approved_revision,0)<>w.content_revision) BEGIN SELECT RAISE(ABORT,'website_client_approval_required'); END;
CREATE TRIGGER website_new_review AFTER UPDATE OF status,banner_status ON projects WHEN NEW.status IN('lead','in_progress') AND (NEW.status<>OLD.status OR NEW.banner_status<>OLD.banner_status) BEGIN UPDATE website_subscription_projects SET content_revision=content_revision+1,approved_revision=NULL,approved_by=NULL,approved_at=NULL WHERE project_id=NEW.id; END;
-- Associate native orders (including renewals) with one exact project and its
-- accepted buyer. No second checkout, payment ledger or account is created.
CREATE TABLE website_subscription_orders(order_id TEXT PRIMARY KEY REFERENCES commerce_orders(id) ON DELETE RESTRICT,project_id TEXT NOT NULL REFERENCES website_subscription_projects(project_id) ON DELETE RESTRICT,acceptance_order_id TEXT NOT NULL REFERENCES website_subscription_acceptances(order_id) ON DELETE RESTRICT);
ALTER TABLE website_subscription_acceptances ADD COLUMN buyer_snapshot_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(buyer_snapshot_json));
CREATE TRIGGER website_acceptance_identity BEFORE INSERT ON website_subscription_acceptances WHEN NOT EXISTS(SELECT 1 FROM website_subscription_projects w JOIN projects p ON p.id=w.project_id WHERE w.project_id=NEW.project_id AND p.owner_user_id=NEW.user_id AND w.plan_id=NEW.plan_id AND w.plan_revision=NEW.plan_revision AND p.client_id=json_extract(NEW.buyer_snapshot_json,'$.clientId')) OR length(coalesce(json_extract(NEW.buyer_snapshot_json,'$.name'),''))<2 OR length(coalesce(json_extract(NEW.buyer_snapshot_json,'$.address'),''))<5 OR length(coalesce(json_extract(NEW.buyer_snapshot_json,'$.email'),''))<3 BEGIN SELECT RAISE(ABORT,'website_acceptance_identity_mismatch'); END;
CREATE TRIGGER website_order_identity BEFORE INSERT ON website_subscription_orders WHEN NOT EXISTS(SELECT 1 FROM website_subscription_acceptances a JOIN commerce_orders o ON o.id=NEW.order_id WHERE a.order_id=NEW.acceptance_order_id AND a.project_id=NEW.project_id AND a.user_id=o.user_id) BEGIN SELECT RAISE(ABORT,'website_order_beneficiary_mismatch'); END;
CREATE TRIGGER website_order_assignment_immutable BEFORE UPDATE ON website_subscription_orders BEGIN SELECT RAISE(ABORT,'immutable_website_order_assignment'); END;
CREATE TRIGGER website_project_beneficiary_immutable BEFORE UPDATE OF client_id ON projects WHEN NEW.client_id IS NOT OLD.client_id AND EXISTS(SELECT 1 FROM website_subscription_projects WHERE project_id=NEW.id) BEGIN SELECT RAISE(ABORT,'website_beneficiary_immutable'); END;
-- Reuse the existing bounded billing reconciliation job; no extra cron/service.
ALTER TABLE website_subscription_projects ADD COLUMN reconciled_at INTEGER NOT NULL DEFAULT 0;
ALTER TABLE website_subscription_projects ADD COLUMN reconcile_cursor TEXT;
CREATE INDEX website_reconciliation_due ON website_subscription_projects(reconciled_at,project_id);
-- Native generic editors must not rewrite a price/plan already accepted.
CREATE TRIGGER website_accepted_plan_immutable BEFORE UPDATE OF plan_id,plan_revision,plan_snapshot_json ON website_subscription_projects WHEN OLD.current_order_id IS NOT NULL AND (NEW.plan_id<>OLD.plan_id OR NEW.plan_revision<>OLD.plan_revision OR NEW.plan_snapshot_json<>OLD.plan_snapshot_json) BEGIN SELECT RAISE(ABORT,'website_accepted_plan_immutable'); END;
CREATE TRIGGER website_accepted_service_immutable BEFORE UPDATE OF price,catalog_code_id ON services WHEN (NEW.price IS NOT OLD.price OR NEW.catalog_code_id IS NOT OLD.catalog_code_id) AND EXISTS(SELECT 1 FROM subscriptions sub JOIN website_subscription_projects w ON w.subscription_id=sub.id WHERE sub.service_id=OLD.id AND w.current_order_id IS NOT NULL) BEGIN SELECT RAISE(ABORT,'website_accepted_plan_immutable'); END;
CREATE TRIGGER website_accepted_sku_immutable BEFORE UPDATE OF plan_sku ON subscriptions WHEN NEW.plan_sku IS NOT OLD.plan_sku AND EXISTS(SELECT 1 FROM website_subscription_projects w WHERE w.subscription_id=OLD.id AND w.current_order_id IS NOT NULL) BEGIN SELECT RAISE(ABORT,'website_accepted_plan_immutable'); END;
CREATE TRIGGER website_accepted_payer_immutable BEFORE UPDATE OF owner_user_id ON projects WHEN NEW.owner_user_id IS NOT OLD.owner_user_id AND EXISTS(SELECT 1 FROM website_subscription_projects w WHERE w.project_id=OLD.id AND w.current_order_id IS NOT NULL) BEGIN SELECT RAISE(ABORT,'website_accepted_plan_immutable'); END;
